/* Generated by tools/build_assets.py. Every available game asset is precached. */
'use strict';
const CACHE_PREFIX = 'ready-set-abc-game-';
const CACHE = CACHE_PREFIX + '__REVISION__';
const PRECACHE = __PRECACHE__;
const OPTIONAL = __OPTIONAL__;
const localURL = path => new URL(path, self.registration.scope).href;
async function storeAvailable(cache) {
  await Promise.all(OPTIONAL.map(async path => {
    try { const response = await fetch(localURL(path), {cache:'reload'}); if(response.ok)await cache.put(localURL(path),response); } catch { /* Explicit production need; visuals work offline. */ }
  }));
}
self.addEventListener('install', event => {
  event.waitUntil((async () => {
    const cache=await caches.open(CACHE);
    // Required files are atomic: an incomplete build never reports offline ready.
    await cache.addAll(PRECACHE.map(path => new Request(localURL(path), {cache:'reload'})));
    await storeAvailable(cache);
    await self.skipWaiting();
  })());
});
self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    for(const key of await caches.keys())if(key.startsWith(CACHE_PREFIX)&&key!==CACHE)await caches.delete(key);
    await self.clients.claim();
  })());
});
self.addEventListener('fetch', event => {
  const request=event.request,url=new URL(request.url);
  if(request.method!=='GET'||url.origin!==self.location.origin||!url.href.startsWith(self.registration.scope))return;
  event.respondWith((async () => {
    const cache=await caches.open(CACHE);
    const saved=await cache.match(request,{ignoreSearch:true});
    if(saved)return saved;
    try {
      const response=await fetch(request);
      if(response.ok&&OPTIONAL.some(path=>localURL(path)===url.href))await cache.put(request,response.clone());
      return response;
    }catch{
      if(request.mode==='navigate')return (await cache.match(localURL('index.html'))) || Response.error();
      return new Response('',{status:404,statusText:'Asset unavailable'});
    }
  })());
});
self.addEventListener('message', event => {
  if(!['CACHE_STATUS','REFRESH_CACHE'].includes(event.data?.type))return;
  event.waitUntil((async () => {
    let ready=false;
    try{
      const cache=await caches.open(CACHE);
      if(event.data.type==='REFRESH_CACHE'){
        await cache.addAll(PRECACHE.map(path => new Request(localURL(path), {cache:'reload'})));await storeAvailable(cache);
      }
      const entries=await cache.keys(),urls=new Set(entries.map(r=>r.url));
      ready=PRECACHE.every(path=>urls.has(localURL(path)));
    }catch{ /* Report a partial cache without blocking local play. */ }
    event.ports[0]?.postMessage({type:'CACHE_STATUS',ready,pending:OPTIONAL.length});
  })());
});
